function randomNonce(bytes: number): string {
  const binary = Array.from(crypto.getRandomValues(new Uint8Array(bytes)), (byte) => String.fromCharCode(byte)).join("");
  return btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/u, "");
}
